            name = _norm_field(ev.get("name", "") or "")
            city = _norm_field(ev.get("city", "") or "")
            source = ev["source"]
            time = ev["time"]

            rec = tmp_records.get(email)

            if rec is None:
                # new record
                rec = {
                    "name": name,
                    "city": city,
                    "first_contact": time,
                    "sources": set(),
                }
                tmp_records[email] = rec
                if name and city:
                    items.append("accepted")
                else:
                    items.append("incomplete")
