                if name and not rec["name"]:
                    rec["name"] = name
                if city and not rec["city"]:
                    rec["city"] = city

                was_complete = bool(rec["name"] and rec["city"])
                # after merge, check completeness
                if rec["name"] and rec["city"]:
                    if not was_complete:
                        items.append("promoted")
                    else:
                        items.append("duplicate")
